// =============================================================================
// Cosmos DB EF Core 9 Breaking Changes — Required Fixes
// =============================================================================
// Apply these patterns in your Cosmos DB project to avoid runtime failures.

using Microsoft.EntityFrameworkCore;

// ---------------------------------------------------------------------------
// BREAKING CHANGE 1: Discriminator property renamed from "Discriminator" to "$type"
// BREAKING CHANGE 2: id property no longer contains the discriminator value
//
// Existing documents use the old "Discriminator" property and compound id
// format ("EntityType|KeyValue"). Without these overrides, EF Core 9 will
// fail to read existing documents.
// ---------------------------------------------------------------------------
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve the EF Core 8 discriminator property name for existing documents
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Preserve the EF Core 8 compound id format ("Session|123") for existing documents
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
}

// ---------------------------------------------------------------------------
// BREAKING CHANGE 3: Synchronous I/O no longer supported on Cosmos DB provider
//
// Calls like SaveChanges(), ToList(), First(), Count(), etc. now throw.
// Replace ALL sync calls with their async equivalents.
// ---------------------------------------------------------------------------
class CosmosQueryExamples
{
    // BREAKS — sync queries throw InvalidOperationException in EF Core 9
    // var sessions = db.Sessions.ToList();
    // var count   = db.Sessions.Count();
    // db.SaveChanges();

    // Fix — use async equivalents
    async Task Example(CosmosDbContext db)
    {
        var sessions = await db.Sessions.ToListAsync();
        var count = await db.Sessions.CountAsync();
        await db.SaveChangesAsync();
    }
}

